// Extract request payload safely
const body = $json.body || $json;

const senderName = body.senderName || 'Sender';
const senderEmail = body.senderEmail || '';
const recipient = body.recipient || 'recipient@example.com';
const reason = body.reason || 'Follow up';
const attachments = Array.isArray(body.attachments) ? body.attachments : [];
const attachmentSummary = body.attachmentSummary || '';

// Format attached files and Google Drive links for text display
let filesContext = 'No attachments';
if (attachments.length > 0) {
  filesContext = attachments.map((att, index) => {
    if (att.source === 'google_drive') {
      return `• [Google Drive Link] ${att.name || 'Document'}: ${att.url}`;
    }
    const sizeKb = att.size ? `${Math.round(att.size / 1024)} KB` : 'file';
    return `• [Computer Upload] ${att.name || 'Attachment'} (${sizeKb})`;
  }).join('\n');
}

return {
  senderName,
  senderEmail,
  recipient,
  reason,
  attachments,
  filesContext
};

const items = [];

for (const item of $input.all()) {
  const json = item.json;
  const attachments = Array.isArray(json.attachments) ? json.attachments : [];
  const reason = json.reason || '';

  // 1. Recipient Name Extraction
  const rawName = json.recipient.split('@')[0].replace(/[0-9_\-\.]+/g, '');
  let recipientName = rawName ? rawName.charAt(0).toUpperCase() + rawName.slice(1) : 'there';
  if (recipientName.toLowerCase().endsWith('op') && recipientName.length > 2) {
    recipientName = recipientName.slice(0, -2);
  }

  // Tone detection
  const isLighthearted = /joke|friendly|lighthearted|fun|humor|laugh|emoji/i.test(reason);
  const hasAlgebra = /algebra|math|calcul|equation|variable/i.test(reason);

  // 2. Intelligent Subject Line
  let subject = 'Important Note from ' + json.senderName;
  if (hasAlgebra) {
    subject = isLighthearted 
      ? 'Why Algebra is Secretly a Superpower 📐✨ (+ Practice Guide)'
      : 'Essential Algebra Concepts & Study Resources';
  } else if (reason.length > 5) {
    const cleanTopic = reason.replace(/^(explaining|telling|asking|informing|sending|please|write|make|draft)\s+(to\s+the\s+receiver\s+)?(how\s+he\s+should\s+|why\s+|that\s+)?/i, '');
    subject = cleanTopic.slice(0, 50).trim() + (cleanTopic.length > 50 ? '...' : '');
    subject = subject.charAt(0).toUpperCase() + subject.slice(1);
  }

  // 3. Proper Email Structure: Greeting & Introduction
  const greeting = 'Hi ' + recipientName + (isLighthearted ? '! 👋' : ',');
  const intro = isLighthearted
    ? 'I hope your week is off to a flying start! I wanted to send over a quick note with some thoughts and helpful resources on what we are working on.'
    : 'I hope this email finds you well. I am reaching out to share some important guidance and resources regarding our current focus.';

  // 4. Structured Multi-Paragraph Body
  let bodyP1 = '';
  let bodyP2 = '';
  let bodyBullets = [];

  if (hasAlgebra && isLighthearted) {
    bodyP1 = 'I know what you might be thinking: "Why do we spend so much time searching for x? x has been missing for years, maybe it just wants to be left alone!" 😂 But jokes aside, algebra is actually one of the coolest hidden superpowers you can master.';
    bodyP2 = 'Think of algebra not as boring letters and numbers, but as real-world puzzle solving and pattern cracking. When you get comfortable with it, you unlock skills that carry over everywhere:';
    bodyBullets = [
      '🎮 Leveling up analytical logic (the exact same problem-solving game developers and AI engineers use)',
      '💡 Making tricky equations and practical questions feel like easy mini-challenges',
      '🚀 Building confidence so advanced technical and science concepts become second nature'
    ];
  } else {
    const cleanReason = reason.replace(/^(explaining|telling|asking|informing)\s+(to\s+the\s+receiver\s+)?/i, '');
    const sentences = cleanReason.split(/[\.\n]+/).map(s => s.trim()).filter(Boolean);
    bodyP1 = sentences[0] ? (sentences[0].charAt(0).toUpperCase() + sentences[0].slice(1) + '.') : 'I wanted to share key insights on this topic with you.';
    if (sentences.length > 1) {
      bodyP2 = sentences.slice(1).join('. ') + '.';
    } else {
      bodyP2 = 'Putting dedicated focus into these concepts will help streamline our progress and ensure strong results moving forward.';
    }
  }

  // 5. Attachment Introduction
  let attachmentNote = '';
  if (attachments.length > 0) {
    const attNames = attachments.map(a => a.name).join(', ');
    attachmentNote = isLighthearted
      ? 'To help you dive in without any stress, I have attached a great resource for you: ' + attNames + '. Take a peek when you have a quiet moment — treat each question like a riddle to crack! 🧩'
      : 'For your review, I have attached the following file(s): ' + attNames + '. Please look through the material at your earliest convenience.';
  }

  // 6. Conclusion & Call to Action
  const conclusion = isLighthearted
    ? 'Give it a look, try a few problems, and definitely let me know if you get stuck on anything! I am always here to walk through a problem or share a shortcut. You have totally got this! 🚀💪'
    : 'Please let me know if you have any questions or require further clarification. I look forward to hearing your thoughts and feedback.';

  const signOff = `Best regards,\n${json.senderName}\n${json.senderEmail}`;

  // Plain Text Body
  const plainTextParts = [greeting, intro, bodyP1, bodyP2];
  if (bodyBullets.length > 0) {
    plainTextParts.push(bodyBullets.map(b => '• ' + b).join('\n'));
  }
  if (attachmentNote) plainTextParts.push(attachmentNote);
  plainTextParts.push(conclusion, signOff);
  const bodyText = plainTextParts.join('\n\n');

  // Build HTML File Retrieval Container
  let fileContainerHtml = '';
  if (attachments.length > 0) {
    const fileCards = attachments.map((att, i) => {
      if (att.source === 'google_drive') {
        return `<div style="padding: 10px 14px; background: #ffffff; border: 1px solid #d2e3fc; border-radius: 8px; margin-bottom: 8px;">` +
          `<span style="background: #e8f0fe; color: #1a73e8; font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 4px; text-transform: uppercase;">Google Drive</span> ` +
          `<strong>${att.name || 'Document'}</strong><br/>` +
          `<a href="${att.url}" target="_blank" style="display: inline-block; margin-top: 6px; color: #1a73e8; text-decoration: underline; font-size: 13px; font-weight: 600;">Open File in Google Drive &rarr;</a>` +
          `</div>`;
      }
      const sizeKb = att.size ? `${Math.round(att.size / 1024)} KB` : 'file';
      return `<div style="padding: 10px 14px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; margin-bottom: 8px;">` +
        `<span style="background: #e0f2fe; color: #0369a1; font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 4px; text-transform: uppercase;">Attachment</span> ` +
        `<strong>${att.name || 'File'}</strong> <span style="color: #64748b; font-size: 12px;">(${sizeKb})</span><br/>` +
        `<span style="font-size: 12px; color: #64748b;">Attached directly to this email for download</span>` +
        `</div>`;
    }).join('');

    fileContainerHtml = `<div style="margin: 22px 0; padding: 16px; background-color: #f8fafc; border: 1.5px solid #cbd5e1; border-radius: 10px;">` +
      `<div style="font-weight: 700; font-size: 14px; color: #0f172a; margin-bottom: 4px;">📎 File Retrieval Container</div>` +
      `<div style="font-size: 12px; color: #64748b; margin-bottom: 12px;">The sender attached the following file(s) for you to view or download:</div>` +
      fileCards +
      `</div>`;
  }

  const bulletListHtml = bodyBullets.length > 0 
    ? `<ul style="margin: 10px 0 16px 20px; padding: 0;">${bodyBullets.map(b => `<li style="margin-bottom: 6px;">${b}</li>`).join('')}</ul>` 
    : '';

  const emailHtml = `<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 620px; color: #1e293b; line-height: 1.6; font-size: 15px;">` +
    `<p style="margin-bottom: 14px;">${greeting}</p>` +
    `<p style="margin-bottom: 14px;">${intro}</p>` +
    `<p style="margin-bottom: 14px;">${bodyP1}</p>` +
    `<p style="margin-bottom: 10px;">${bodyP2}</p>` +
    bulletListHtml +
    (attachmentNote ? `<p style="margin-bottom: 14px;">${attachmentNote}</p>` : '') +
    fileContainerHtml +
    `<p style="margin-bottom: 16px;">${conclusion}</p>` +
    `<p style="margin-top: 24px; border-top: 1px solid #e2e8f0; padding-top: 14px;">Best regards,<br/><strong>${json.senderName}</strong><br/><span style="color: #64748b;">${json.senderEmail}</span></p>` +
    `</div>`;

  // Process binary attachments
  const binary = {};
  for (let i = 0; i < attachments.length; i++) {
    const att = attachments[i];
    if (att.source === 'computer' && att.data) {
      try {
        const base64Data = att.data.includes(',') ? att.data.split(',')[1] : att.data;
        const buffer = Buffer.from(base64Data, 'base64');
        const propName = i === 0 ? 'data' : `data_${i}`;
        binary[propName] = await this.helpers.prepareBinaryData(
          buffer,
          att.name || `attachment_${i + 1}.pdf`,
          att.type || 'application/octet-stream'
        );
      } catch (e) {}
    }
  }

  const hasBinaryAttachment = Object.keys(binary).length > 0;

  const formattedResult = `✉️ Email Verified & Sent!\n\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `To: ${json.recipient}\n` +
    `From: ${json.senderName} <${json.senderEmail}>\n` +
    `Subject: ${subject}\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
    `${bodyText}\n\n` +
    (attachments.length > 0 ? `📎 Attached Items (${attachments.length}):\n${json.filesContext}\n\n` : '') +
    `✅ Verification: Introduction, multi-paragraph body, tone tuning, and conclusion successfully composed.`;

  items.push({
    json: {
      recipient: json.recipient,
      senderEmail: json.senderEmail,
      senderName: json.senderName,
      subject: subject,
      emailBody: bodyText,
      emailHtml: emailHtml,
      attachmentsCount: attachments.length,
      filesContext: json.filesContext,
      formattedDraft: formattedResult,
      hasBinaryAttachment: hasBinaryAttachment
    },
    binary: hasBinaryAttachment ? binary : undefined
  });
}

return items;

const draft = $('Draft & Prepare Attachments').first().json;
const gmailOutput = $json;

const confirmationText = `🚀 Email & Attachments Delivered!\n\n` +
  `Recipient: ${draft.recipient}\n` +
  (gmailOutput.id ? `Gmail ID: ${gmailOutput.id}\n` : '') +
  `Attachments Sent: ${draft.attachmentsCount}\n\n` +
  draft.formattedDraft;

return {
  status: 'success',
  result: confirmationText,
  recipient: draft.recipient,
  subject: draft.subject,
  messageId: gmailOutput.id || 'sent'
};
